const R=EvervaleRules,DB=EvervaleContent,$=id=>document.getElementById(id),escapeHTML=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const places={work:['ย่านช่างฝีมือ','ทำงานรับ 18 เหรียญ ใช้พลังงาน 12','ทำงาน'],train:['ลานฝึก','ฝึกดาบ +8 EXP จ่าย 8 เหรียญ ใช้พลังงาน 15','ฝึกดาบ'],study:['หอเวท','เรียนเวท +8 EXP จ่าย 12 เหรียญ ใช้พลังงาน 13','เรียนเวท'],explore:['ป่ากระซิบ','เข้าสนามต่อสู้ • ชนะเพื่อรับเหรียญและ EXP','ออกสำรวจ'],rest:['โรงเตี๊ยม','ฟื้นพลังงาน 35 สุขภาพ 12 และมานา 25','พักฟื้น']};
const classEffects={warrior:'ฝึกดาบ +2 EXP',rogue:'สำรวจ +4 เหรียญ',mage:'เรียนเวท +2 EXP',priest:'พักฟื้นสุขภาพเพิ่ม 6',ranger:'สำรวจใช้พลังงานน้อยลง 3',buffer:'ผลสกิลที่เตรียมไว้เพิ่มอีก 2',alchemist:'เรียนเวทใช้เงินน้อยลง 2',knight:'ความเสียหายสำรวจลดลง 3'};
let s=R.fresh(),uid=null,storageKey=null,selected='work',screen='menuScreen',returnScreen='menuScreen',notice='',newDraft=false;
function calendar(day,minute){const d=new Date(0);d.setUTCFullYear(1,0,1);d.setUTCDate(1+day);return `วันที่ ${d.getUTCDate()} เดือน ${d.getUTCMonth()+1} ปี ${d.getUTCFullYear()} · ${String(Math.floor(minute/60)).padStart(2,'0')}:${String(minute%60).padStart(2,'0')} น.`;}
function status(text){$('globalStatus').textContent=text;}
function save(){if(!uid||!s.character)return;s.contentEdits=DB.overrides||{};try{localStorage.setItem(storageKey,JSON.stringify(s));}catch{status('พื้นที่เซฟในเครื่องไม่พอ • กำลังส่งเซฟขึ้นคลาวด์ หากยังไม่ได้ซิงก์ให้ส่งออกไฟล์สำรอง');}window.dispatchEvent(new Event('evervale-save'));}
function show(id){if(!uid)return;if(screen==='battleEditorScreen'&&id!==screen&&window.EverTaleBattle&&!EverTaleBattle.canLeave())return;if(screen==='mapEditorScreen'&&id!==screen&&window.EvervaleMaps&&!EvervaleMaps.canLeave())return;for(const n of ['menuScreen','createScreen','loadScreen','databaseScreen','settingsScreen','gameScreen','mapEditorScreen','battleEditorScreen','combatScreen'])$(n).hidden=n!==id;screen=id;status('');if(id==='gameScreen'){if(!s.character){openCreate(false);return;}render();}if(id==='databaseScreen'){const full=returnScreen==='menuScreen';$('dbTitle').textContent=full?'ฐานข้อมูลเกมทั้งหมด':'บันทึกสิ่งที่ค้นพบ';$('dbIntro').textContent=full?'ข้อมูลครบ 13 หมวดจากเกมเก่า • เปิดดูและแก้ไขได้ก่อนสร้างตัวละคร • คำอธิบายกลไกต้นฉบับไม่ได้ยืนยันว่าระบบใหม่รองรับแล้ว':'ฐานข้อมูลตัวละครแสดงเฉพาะสิ่งที่ค้นพบ • เปิดฐานข้อมูลจากเมนูหลักเพื่อดูและแก้ไขรายการทั้งหมด';$('dbEditorTools').hidden=!full;renderDatabase();}if(id==='loadScreen')loadInfo();if(id==='mapEditorScreen')window.EvervaleMaps?.openEditor();if(id==='battleEditorScreen')window.EverTaleBattle?.open();window.scrollTo(0,0);}
function setAccount(user){window.EverTaleCombat?.reset();uid=user?.id||null;storageKey=uid?'evervale-life-v3:'+uid:null;s=R.fresh();notice='';$('signedIn').hidden=!uid;$('loginScreen').hidden=!!uid;DB.overrides={};window.EverTaleCharacterArt?.reset();window.EvervaleMaps?.reset();window.EverTaleBattle?.reset();if(!uid)return;try{DB.overrides=validateContentEdits(JSON.parse(localStorage.getItem('evervale-content:'+uid)||'{}'));}catch{}$('accountLabel').textContent='ID · '+(user.user_metadata?.player_id||user.email?.split('@')[0]||'ผู้เดินทาง');try{const data=localStorage.getItem(storageKey);if(data){s=R.validate(JSON.parse(data),DB);if(!Object.keys(DB.overrides).length&&s.contentEdits)DB.overrides=validateContentEdits(s.contentEdits);}}catch{status('เซฟในเครื่องอ่านไม่ได้ • สามารถโหลดคลาวด์หรือนำเข้าไฟล์ได้');}show('menuScreen');$('menuNote').textContent=s.character?'ยินดีต้อนรับกลับ '+s.character.name+' • โหลดเซฟเพื่อเล่นต่อ':'ยังไม่มีตัวละครในเครื่องนี้ • เริ่มเกมใหม่หรือโหลดเซฟคลาวด์';}
function openCreate(isNew){newDraft=isNew;$('createStatus').textContent='';$('characterName').value='';window.EverTaleCharacterArt?.resetCreation(!isNew?s.character?.images:null);show('createScreen');creationSummary();}
function creationSummary(){const race=R.races.find(x=>x[0]===document.querySelector('[name=race]:checked')?.value)||R.races[0],job=R.classes.find(x=>x[0]===document.querySelector('[name=job]:checked')?.value)||R.classes[0];$('creationSummary').innerHTML=`<h2>${escapeHTML(race[1])} · ${escapeHTML(job[1])}</h2><p>${escapeHTML(race[2])}</p><p>Passive: ${escapeHTML(job[3])} (${classEffects[job[0]]}) • Active: ${escapeHTML(job[4])} / ${escapeHTML(job[5])}</p><p>ค่าสถานะเริ่มต้นทุกค่า 10 • ${job[7]} +4 และ CON +2 • เลเวล 1 • เงิน 120 เหรียญ</p><p class="muted">สกิลเผ่าและผลกิจกรรมเป็นร่างปรับสมดุล • คลาสรอง คลาสพิเศษ และลูกหลานจะพัฒนาภายหลัง</p>`;}
$('raceChoices').innerHTML=R.races.map((x,i)=>`<label class="choice"><input type="radio" name="race" value="${x[0]}" ${i===0?'checked':''}><span><strong>${x[1]}</strong><small>${x[2]}</small></span></label>`).join('');
$('classChoices').innerHTML=R.classes.map((x,i)=>`<label class="choice"><input type="radio" name="job" value="${x[0]}" ${i===0?'checked':''}><span><strong>${x[1]}</strong><small>${escapeHTML(x[4])} / ${escapeHTML(x[5])}</small></span></label>`).join('');
document.querySelectorAll('[name=race],[name=job]').forEach(x=>x.onchange=creationSummary);
$('createForm').onsubmit=e=>{e.preventDefault();try{const next=newDraft?R.fresh():JSON.parse(JSON.stringify(s));R.createCharacter(next,$('characterName').value,document.querySelector('[name=race]:checked').value,document.querySelector('[name=job]:checked').value,DB);next.character.images=window.EverTaleCharacterArt?.creationImages()||R.validateCharacterImages();if(newDraft&&s.character)localStorage.setItem(storageKey+':backup',JSON.stringify(s));s=next;R.log(s,'เดินทางถึง Decide Fate • '+s.character.name);save();fields();show('gameScreen');}catch(e){$('createStatus').textContent=e.message;}};
$('newGame').onclick=()=>{if(s.character&&!confirm('สร้างชีวิตใหม่? เซฟปัจจุบันจะถูกสำรองในเครื่อง และแทนที่เมื่อสร้างตัวละครสำเร็จ'))return;openCreate(true);};
$('loadMenu').onclick=()=>{show('loadScreen');window.EvervaleCloud?.refresh();};$('databaseMenu').onclick=()=>{returnScreen='menuScreen';show('databaseScreen');};$('settingsMenu').onclick=()=>{returnScreen='menuScreen';show('settingsScreen');};$('menuButton').onclick=()=>show('menuScreen');
document.querySelectorAll('[data-back]').forEach(x=>x.onclick=()=>show(['databaseScreen','settingsScreen'].includes(screen)?returnScreen:'menuScreen'));
$('gameDatabase').onclick=()=>{returnScreen='gameScreen';show('databaseScreen');};$('gameSettings').onclick=()=>{returnScreen='gameScreen';show('settingsScreen');};$('settingsLoad').onclick=()=>{show('loadScreen');window.EvervaleCloud?.refresh();};
function loadInfo(){let local=null;try{local=JSON.parse(localStorage.getItem(storageKey));}catch{}$('localSaveInfo').textContent=local?.character?local.character.name+' • เลเวล '+local.character.level+' • '+calendar(local.days,local.minute):'ยังไม่มีเซฟของบัญชีนี้ในเครื่อง';$('legacyLoad').hidden=!localStorage.getItem('evervale-life-v1');$('localLoad').disabled=!local;$('exportSave').disabled=!s.character;}
$('localLoad').onclick=()=>{try{s=R.validate(JSON.parse(localStorage.getItem(storageKey)),DB);fields();show(s.character?'gameScreen':'createScreen');}catch(e){$('loadStatus').textContent=e.message;}};
$('legacyLoad').onclick=()=>{try{if(!confirm('เซฟเก่าในเครื่องนี้อาจเป็นของผู้ใช้คนอื่น นำมาใช้กับบัญชีนี้หรือไม่? เซฟต้นฉบับจะยังอยู่'))return;EvervaleSave.load(JSON.parse(localStorage.getItem('evervale-life-v1')));}catch(e){$('loadStatus').textContent=e.message;}};
$('exportSave').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(s,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='evertale-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('importSave').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>6000000)throw Error('ไฟล์เซฟใหญ่เกิน 6 MB');const next=R.validate(JSON.parse(await f.text()),DB);if(!confirm('นำเข้าเซฟนี้แทนเซฟในเครื่องของบัญชีนี้? ระบบจะสำรองเซฟปัจจุบันก่อน'))return;localStorage.setItem(storageKey+':backup',JSON.stringify(s));s=next;if(s.contentEdits){DB.overrides=validateContentEdits(s.contentEdits);localStorage.setItem('evervale-content:'+uid,JSON.stringify(DB.overrides));window.dispatchEvent(new Event('evervale-content-save'));}if(s.character)save();else localStorage.setItem(storageKey,JSON.stringify(s));fields();if(!s.character){openCreate(false);$('createStatus').textContent='เซฟเก่ายังคงเงินและความก้าวหน้าเดิมไว้ เลือกตัวตนเพื่อเล่นต่อ';}else show('gameScreen');}catch(err){$('loadStatus').textContent=err.message;}finally{e.target.value='';}};
$('largeText').checked=localStorage.getItem('evervale-large-text')==='true';document.body.classList.toggle('large-text',$('largeText').checked);$('largeText').onchange=()=>{localStorage.setItem('evervale-large-text',String($('largeText').checked));document.body.classList.toggle('large-text',$('largeText').checked);};
function fields(){$('plan').value=s.plan;$('reserve').value=s.reserve;$('threshold').value=s.threshold;$('safe').checked=s.safe;$('thresholdText').textContent=s.threshold+'/100';}
function render(){if(!s.character)return;const c=s.character,race=R.races.find(x=>x[0]===c.race),job=R.classes.find(x=>x[0]===c.job);$('characterPanel').innerHTML=`<div><p class="eyebrow">YOUR CHARACTER</p><h2>${escapeHTML(c.name)} <span class="tag">Lv.${c.level}</span></h2><p>${race[1]} · ${job[1]} • EXP ${c.xp}/${c.level*50}</p><div class="attributes">${Object.entries(c.stats).map(([k,v])=>`<span>${k}<b>${v}</b></span>`).join('')}</div></div><div><p>Passive · ${job[3]} (${classEffects[c.job]}) / ${race[2]}</p><div class="skills">${[...new Set([job[4],job[5],...s.learned.map(key=>R.records(DB).find(x=>x.key===key)).filter(row=>row&&R.playable(row)).map(row=>row.name)])].map(n=>`<button data-skill="${escapeHTML(n)}" ${s.dead||s.event||s.expedition||s.buff||s.mp<5?'disabled':''}>${escapeHTML(n)} · 5 MP</button>`).join('')}</div><p class="skill-note">เตรียมสกิลแล้วทำกิจกรรม: ฝึก/เรียน +${c.job==='buffer'?6:4} EXP, สำรวจ +${c.job==='buffer'?6:4} เหรียญและลดบาดเจ็บเท่ากัน, พักเพิ่มเท่ากัน • ใช้ผลครั้งเดียว</p><p class="skill-note">${s.buff?'เตรียมไว้: '+escapeHTML(s.buff):'ยังไม่ได้เตรียมสกิล'} • มานา ${s.mp}/${s.maxMp}</p></div>`;
document.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>{try{R.useSkill(s,b.dataset.skill,DB);save();render();}catch(e){status(e.message);}});
$('date').textContent=calendar(s.days,s.minute);$('age').textContent=`อายุ ${Math.floor(s.ageStart+s.days/365)} ปี ${s.days%365} วัน`;$('progress').style.width=s.minute/1440*100+'%';$('stats').innerHTML=[['เหรียญ',s.gold.toLocaleString()],['สุขภาพ',s.hp+'/100'],['พลังงาน',s.energy+'/100'],['ดาบ · EXP',s.sword],['เวท · EXP',s.magic]].map(([k,v])=>`<div class="stat"><span>${k}</span><strong>${v}</strong></div>`).join('');document.querySelectorAll('.place').forEach(b=>b.classList.toggle('selected',b.dataset.place===selected));const p=places[selected];$('location').innerHTML=`<p class="eyebrow">${s.dead?'LIFE COMPLETE':'YOUR NEXT ACTION'}</p><h2>${s.dead?'บันทึกชีวิตบทนี้จบลงแล้ว':p[0]}</h2><p>${s.dead?'กลับเมนูเพื่อเริ่มชีวิตใหม่':p[1]+' • ใช้เวลา '+(selected==='explore'?2:R.durations[selected]/60)+' ชั่วโมงในเกม • โบนัสเผ่า คลาส และสกิลคำนวณเพิ่มตามตัวละคร'}</p><button class="primary" id="manual" ${s.dead||s.event?'disabled':''}>${p[2]}ตอนนี้</button><p class="muted">หากพลังต่ำจะพักก่อน และหากเงินต่ำกว่าเงินสำรองจะทำงานก่อน • เวลาเดินตามกิจกรรมที่ทำจริง</p>`;$('manual').onclick=()=>run(1,selected);
$('logs').replaceChildren();s.logs.slice(0,9).forEach(l=>{const d=document.createElement('div');d.className='log';const stamp=document.createElement('small');stamp.textContent=calendar(l.day,l.minute??480);d.append(stamp,document.createTextNode(l.text));$('logs').append(d);});$('mode').textContent=s.dead?'จบชีวิต':'● รอการตัดสินใจของคุณ';$('planStatus').textContent=notice||'แผนที่ใช้อยู่: '+places[s.plan][2];$('score').textContent=s.ach.length*10+' แต้ม';$('achievements').innerHTML=[['first','เงินก้อนแรก'],['blade','นักดาบฝึกหัด'],['mage','ประกายเวท'],['wild','สำรวจครบ 10 ครั้ง'],['wealth','มีเงิน 1,000 เหรียญ']].map(([id,t])=>`<div class="badge ${s.ach.includes(id)?'unlocked':''}">${s.ach.includes(id)?'✦':'◇'} ${t} <small>+10</small></div>`).join('');$('event').hidden=!s.event;if(s.event?.type==='eye'){$('event').innerHTML='<p class="eyebrow">RARE ENCOUNTER</p><h2>คิซิลิก้า · ผู้มอบเนตร</h2><p>เกียฮะฮะฮะ! เลี้ยงอาหารข้าสิ แล้วข้าจะมอบดวงตาปีศาจให้เจ้า!</p><p>เลี้ยงอาหาร 20 เหรียญ • สุ่มเท่ากันจากเนตรที่คุณยังไม่มี 9 ชนิด</p><button class="primary" id="feedEye">เลี้ยงอาหารและรับเนตร</button><button id="declineEye">ไว้พบกันใหม่</button>';$('feedEye').disabled=s.gold<20||DB.eyes.every(x=>R.has(s,x.skillName,DB));$('feedEye').onclick=()=>{const eye=R.grantEye(s,DB);if(!eye){status('ไม่สามารถมอบเนตรได้ • ไม่หักเงิน');return;}save();render();};$('declineEye').onclick=()=>{s.event=null;R.log(s,'บอกลาคิซิลิก้า');save();render();};}$('day').disabled=$('offline').disabled=s.dead||!!s.event;window.EverTaleCharacterArt?.renderCharacter();window.EvervaleMaps?.renderGame();window.EverTaleCombat?.entry();}
function run(n,action){if(s.expedition){window.EverTaleCombat?.launch();return;}if(n===1&&(action||s.plan)==='explore'&&!s.dead&&!s.event&&s.hp>=45&&s.energy>=Math.max(15,s.threshold)&&s.gold>=s.reserve){window.EverTaleCombat?.launch('forest');return;}let count=0;for(;count<n&&!s.dead&&!s.event;count++)R.act(s,action||s.plan,DB);notice='ดำเนินกิจกรรมแล้ว '+count+' ครั้ง'+(s.event?' • หยุดรอคำตอบอีเวนต์':'');save();render();}
document.querySelectorAll('.place').forEach(b=>b.onclick=()=>{selected=b.dataset.place;render();});$('threshold').oninput=()=>{$('thresholdText').textContent=$('threshold').value+'/100';};$('savePlan').onclick=()=>{s.plan=$('plan').value;s.reserve=Math.max(0,Math.min(10000,Number($('reserve').value)||0));s.threshold=Number($('threshold').value);s.safe=$('safe').checked;notice='บันทึกแผนชีวิตแล้ว';save();render();};$('pause').onclick=()=>{save();notice='บันทึกแล้ว • เวลาไม่เดินขณะปิดเกม';render();};$('day').onclick=()=>run(1);$('offline').onclick=()=>{if(s.expedition||s.plan==='explore'){run(1,s.plan);return;}const start=s.days*1440+s.minute;let count=0;while(!s.dead&&!s.event&&s.days*1440+s.minute-start<1440&&count++<24)R.act(s,s.plan,DB);notice='ดำเนินแผนแล้ว '+(s.days*1440+s.minute-start)/60+' ชั่วโมง'+(s.event?' • หยุดรอคำตอบอีเวนต์':'');save();render();};$('reset').onclick=$('newGame').onclick;
$('dbSearch').oninput=renderDatabase;$('dbKind').onchange=renderDatabase;
window.EvervaleSave={snapshot:()=>JSON.parse(JSON.stringify(s)),hasCharacter:()=>!!s.character,emptySnapshot:()=>R.fresh(),cacheContent(data){s.contentEdits=JSON.parse(JSON.stringify(data));if(uid&&s.character){try{localStorage.setItem(storageKey,JSON.stringify(s));}catch{status('รูปบันทึกในฐานข้อมูลแล้ว แต่สำเนาเซฟในเครื่องเต็ม');}}},setAccount,load(data){const next=R.validate(data,DB);const edits=next.contentEdits?validateContentEdits(next.contentEdits):null;if(edits){localStorage.setItem('evervale-content:'+uid,JSON.stringify(edits));DB.overrides=edits;}if(s.character)localStorage.setItem(storageKey+':backup',JSON.stringify(s));s=next;if(s.character)save();else localStorage.setItem(storageKey,JSON.stringify(s));fields();if(!s.character){openCreate(false);$('createStatus').textContent='โหลดเซฟเก่าแล้ว • เลือกตัวตนก่อนเล่นต่อ เงินและความก้าวหน้าเดิมยังอยู่';}else show('gameScreen');},isDirty:()=>!!s.character};
function renderDatabase(){window.EvervaleEditor?.renderDatabase();}
